const crypto = require("crypto");
// ---- services/common/src/discord.js ----

const InteractionType = { PING: 1, COMMAND: 2, COMPONENT: 3, AUTOCOMPLETE: 4, MODAL_SUBMIT: 5 };
const ResponseType = { PONG: 1, MESSAGE: 4, DEFERRED_MESSAGE: 5, DEFERRED_UPDATE: 6, UPDATE_MESSAGE: 7, MODAL: 9 };
const EPHEMERAL = 64;

const ED25519_SPKI_PREFIX = Buffer.from("302a300506032b6570032100", "hex");

function verifyDiscordSignature(rawBody, signature, timestamp, publicKeyHex) {
  if (!signature || !timestamp || !publicKeyHex) return false;
  try {
    const key = crypto.createPublicKey({
      key: Buffer.concat([ED25519_SPKI_PREFIX, Buffer.from(publicKeyHex, "hex")]),
      format: "der",
      type: "spki",
    });
    return crypto.verify(null, Buffer.from(timestamp + rawBody), key, Buffer.from(signature, "hex"));
  } catch {
    return false;
  }
}

const ephemeral = (content) => ({ type: ResponseType.MESSAGE, data: { content, flags: EPHEMERAL } });

const linkButton = (label, url) => ({ type: 2, style: 5, label, url });
const actionButton = (label, customId, { style = 2, disabled = false } = {}) => ({
  type: 2, style, label, custom_id: customId, disabled,
});
const row = (...components) => ({ type: 1, components: components.filter(Boolean) });

const roleMention = (id) => `<@&${id}>`;
const userMention = (id) => `<@${id}>`;

function interactionUser(body) {
  const user = body.member?.user ?? body.user ?? {};
  return { id: user.id, name: body.member?.nick || user.global_name || user.username || user.id };
}

function createDiscord(ctx) {
  const { http, env } = ctx;
  const base = (env.DISCORD_API_URL || "https://discord.com/api/v10").replace(/\/$/, "");
  const headers = { Authorization: `Bot ${env.DISCORD_BOT_TOKEN || ""}`, "Content-Type": "application/json" };

  async function call(method, path, body, { auth = true } = {}) {
    const res = await http({
      method, url: `${base}${path}`, body, json: true,
      headers: auth ? headers : { "Content-Type": "application/json" },
      returnFullResponse: true, ignoreHttpStatusErrors: true,
    });
    if (res.statusCode >= 300) {
      const err = new Error(`Discord ${method} ${path}: ${res.statusCode} ${JSON.stringify(res.body)}`);
      err.statusCode = res.statusCode;
      throw err;
    }
    return res.body;
  }

  const emojiPath = (emoji) => encodeURIComponent(emoji);

  return {
    postMessage: (channelId, message) => call("POST", `/channels/${channelId}/messages`, message),
    editMessage: (channelId, messageId, patch) => call("PATCH", `/channels/${channelId}/messages/${messageId}`, patch),
    deleteMessage: (channelId, messageId) => call("DELETE", `/channels/${channelId}/messages/${messageId}`),
    addReaction: (channelId, messageId, emoji) =>
      call("PUT", `/channels/${channelId}/messages/${messageId}/reactions/${emojiPath(emoji)}/@me`),
    removeOwnReaction: (channelId, messageId, emoji) =>
      call("DELETE", `/channels/${channelId}/messages/${messageId}/reactions/${emojiPath(emoji)}/@me`),
    editOriginalResponse: (interactionToken, patch) =>
      call("PATCH", `/webhooks/${env.DISCORD_BOT_ID}/${interactionToken}/messages/@original`, patch, { auth: false }),
  };
}

// ---- services/discord-router/src/router.js ----
// One Discord Interactions Endpoint for the whole bot.
// Verifies the signature, answers PING and forwards every other interaction to its owner's
// internal webhook: POST {MF_INTERNAL_URL}/mentorflow/internal/<target>. The owner answers with
// a Discord interaction response, which the router returns to Discord unchanged.

const PREFIX_TARGETS = { pr: "pr", mt: "mt", menu: "menu", cal: "cal", fb: "fb" };
const COMMAND_TARGETS = { mentor: "menu" };

function routeFor(body) {
  if (body.type === InteractionType.COMMAND || body.type === InteractionType.AUTOCOMPLETE)
    return COMMAND_TARGETS[body.data?.name] ?? null;
  if (body.type === InteractionType.COMPONENT || body.type === InteractionType.MODAL_SUBMIT) {
    const prefix = String(body.data?.custom_id ?? "").split(":")[0];
    return PREFIX_TARGETS[prefix] ?? null;
  }
  return null;
}

const internalUrl = (env, target) =>
  `${(env.MF_INTERNAL_URL || "http://localhost:5678/webhook").replace(/\/$/, "")}/mentorflow/internal/${target}`;

const isInternalCall = (headers, env) =>
  !!env.MF_INTERNAL_SECRET && headers?.["x-mentorflow-secret"] === env.MF_INTERNAL_SECRET;

async function handleInteraction(ctx, rawBody, headers) {
  const { env, http } = ctx;
  if (!verifyDiscordSignature(rawBody, headers["x-signature-ed25519"], headers["x-signature-timestamp"], env.DISCORD_BOT_PUBLIC_KEY))
    return { status: 401, response: { error: "invalid request signature" } };

  const body = JSON.parse(rawBody);
  if (body.type === InteractionType.PING) return { status: 200, response: { type: ResponseType.PONG } };

  const target = routeFor(body);
  if (!target) return { status: 200, response: ephemeral("Unknown action.") };

  try {
    const res = await http({
      method: "POST", url: internalUrl(env, target), body, json: true,
      headers: { "Content-Type": "application/json", "X-MentorFlow-Secret": env.MF_INTERNAL_SECRET || "" },
      timeout: 2500,
      returnFullResponse: true, ignoreHttpStatusErrors: true,
    });
    if (res.statusCode === 404) return { status: 200, response: ephemeral("This feature is not available yet.") };
    if (res.statusCode >= 300 || !res.body?.type) return { status: 200, response: ephemeral("Something went wrong. Please try again.") };
    return { status: 200, response: res.body };
  } catch {
    return { status: 200, response: ephemeral("The bot is busy. Please try again.") };
  }
}

// ---- services/common/src/firestore.js ----
// Auth: FIRESTORE_TOKEN for the emulator, otherwise a service account from FIREBASE_SERVICE_ACCOUNT (JSON or base64).

function toFirestoreValue(v) {
  if (v === null || v === undefined) return { nullValue: null };
  if (v instanceof Date) return { timestampValue: v.toISOString() };
  if (typeof v === "boolean") return { booleanValue: v };
  if (typeof v === "number")
    return Number.isInteger(v) ? { integerValue: String(v) } : { doubleValue: v };
  if (typeof v === "string") return { stringValue: v };
  if (Array.isArray(v)) return { arrayValue: { values: v.map(toFirestoreValue) } };
  return { mapValue: { fields: toFirestoreFields(v) } };
}

function toFirestoreFields(obj) {
  const fields = {};
  for (const [k, v] of Object.entries(obj)) if (v !== undefined) fields[k] = toFirestoreValue(v);
  return fields;
}

function fromFirestoreValue(v) {
  if ("nullValue" in v) return null;
  if ("booleanValue" in v) return v.booleanValue;
  if ("integerValue" in v) return Number(v.integerValue);
  if ("doubleValue" in v) return v.doubleValue;
  if ("stringValue" in v) return v.stringValue;
  if ("timestampValue" in v) return new Date(v.timestampValue).toISOString();
  if ("arrayValue" in v) return (v.arrayValue.values ?? []).map(fromFirestoreValue);
  if ("mapValue" in v) return fromFirestoreFields(v.mapValue.fields ?? {});
  return null;
}

function fromFirestoreFields(fields) {
  const obj = {};
  for (const [k, v] of Object.entries(fields ?? {})) obj[k] = fromFirestoreValue(v);
  return obj;
}

const OPS = { "==": "EQUAL", "!=": "NOT_EQUAL", "<": "LESS_THAN", "<=": "LESS_THAN_OR_EQUAL", ">": "GREATER_THAN", ">=": "GREATER_THAN_OR_EQUAL", in: "IN" };

function buildQuery(collection, where = [], { orderBy, limit } = {}) {
  const filters = where.map(([field, op, value]) => ({
    fieldFilter: { field: { fieldPath: field }, op: OPS[op], value: toFirestoreValue(value) },
  }));
  const q = { from: [{ collectionId: collection }] };
  if (filters.length === 1) q.where = filters[0];
  if (filters.length > 1) q.where = { compositeFilter: { op: "AND", filters } };
  if (orderBy) q.orderBy = [{ field: { fieldPath: orderBy[0] }, direction: orderBy[1] === "desc" ? "DESCENDING" : "ASCENDING" }];
  if (limit) q.limit = limit;
  return { structuredQuery: q };
}

const b64url = (buf) => Buffer.from(buf).toString("base64").replace(/=+$/, "").replace(/\+/g, "-").replace(/\//g, "_");

function serviceAccountJwt(sa, now = new Date()) {
  const iat = Math.floor(now / 1000);
  const header = b64url(JSON.stringify({ alg: "RS256", typ: "JWT" }));
  const claims = b64url(JSON.stringify({
    iss: sa.client_email,
    scope: "https://www.googleapis.com/auth/datastore",
    aud: sa.token_uri ?? "https://oauth2.googleapis.com/token",
    iat,
    exp: iat + 3600,
  }));
  const signature = crypto.createSign("RSA-SHA256").update(`${header}.${claims}`).sign(sa.private_key);
  return `${header}.${claims}.${b64url(signature)}`;
}

function readServiceAccount(env) {
  if (!env.FIREBASE_SERVICE_ACCOUNT) return null;
  const raw = env.FIREBASE_SERVICE_ACCOUNT.trim();
  return JSON.parse(raw.startsWith("{") ? raw : Buffer.from(raw, "base64").toString("utf8"));
}

function createFirestore(ctx) {
  const { http, env } = ctx;
  const sa = readServiceAccount(env);
  const projectId = env.FIREBASE_PROJECT_ID || sa?.project_id;
  if (!projectId) throw new Error("FIREBASE_PROJECT_ID is not set");
  const base = `${(env.FIRESTORE_URL || "https://firestore.googleapis.com/v1").replace(/\/$/, "")}/projects/${projectId}/databases/(default)/documents`;
  let token = env.FIRESTORE_TOKEN || null;

  async function authHeader() {
    if (!token) {
      if (!sa) throw new Error("FIRESTORE_TOKEN or FIREBASE_SERVICE_ACCOUNT is required");
      const res = await http({
        method: "POST",
        url: sa.token_uri ?? "https://oauth2.googleapis.com/token",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: `grant_type=${encodeURIComponent("urn:ietf:params:oauth:grant-type:jwt-bearer")}&assertion=${serviceAccountJwt(sa)}`,
        json: true,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
      });
      if (res.statusCode >= 300) throw new Error(`Google token: ${res.statusCode} ${JSON.stringify(res.body)}`);
      token = res.body.access_token;
    }
    return { Authorization: `Bearer ${token}` };
  }

  async function call(method, url, body) {
    const res = await http({
      method, url, body, json: true,
      headers: { ...(await authHeader()), "Content-Type": "application/json" },
      returnFullResponse: true, ignoreHttpStatusErrors: true,
    });
    return res;
  }

  const fail = (what, res) => { throw new Error(`Firestore ${what}: ${res.statusCode} ${JSON.stringify(res.body)}`); };
  const docOf = (d) => ({ id: d.name.split("/").pop(), ...fromFirestoreFields(d.fields) });

  return {
    async get(path) {
      const res = await call("GET", `${base}/${path}`);
      if (res.statusCode === 404) return null;
      if (res.statusCode >= 300) fail(`get ${path}`, res);
      return docOf(res.body);
    },
    // full write: creates or replaces the document
    async set(path, data) {
      const res = await call("PATCH", `${base}/${path}`, { fields: toFirestoreFields(data) });
      if (res.statusCode >= 300) fail(`set ${path}`, res);
      return docOf(res.body);
    },
    // partial write of top-level fields; creates the document if it does not exist
    async update(path, data) {
      const mask = Object.keys(data).map((k) => `updateMask.fieldPaths=${encodeURIComponent(k)}`).join("&");
      const res = await call("PATCH", `${base}/${path}?${mask}`, { fields: toFirestoreFields(data) });
      if (res.statusCode >= 300) fail(`update ${path}`, res);
      return docOf(res.body);
    },
    async add(collection, data) {
      const res = await call("POST", `${base}/${collection}`, { fields: toFirestoreFields(data) });
      if (res.statusCode >= 300) fail(`add ${collection}`, res);
      return docOf(res.body);
    },
    async delete(path) {
      const res = await call("DELETE", `${base}/${path}`);
      if (res.statusCode >= 300 && res.statusCode !== 404) fail(`delete ${path}`, res);
    },
    async query(collection, where, opts) {
      const res = await call("POST", `${base}:runQuery`, buildQuery(collection, where, opts));
      if (res.statusCode >= 300) fail(`query ${collection}`, res);
      return (res.body ?? []).filter((r) => r.document).map((r) => docOf(r.document));
    },
  };
}

// ---- services/common/src/settings.js ----
// settings/main merged over defaults; environment variables are fallbacks until the mentor panel sets them.

const LABEL_ROLE_ENV = {
  dev: "DEVELOPER_ROLE_ID",
  devops: "DEVOPS_ROLE_ID",
  qa: "STUDENT_QA_ID",
  qc: "STUDENT_QC_ID",
};

function labelRolesFromEnv(env) {
  return Object.fromEntries(Object.entries(LABEL_ROLE_ENV).filter(([, key]) => env[key]).map(([label, key]) => [label, env[key]]));
}

function defaultSettings(env = {}) {
  return {
    channels: {
      prReview: env.PR_REVIEW_CHANNEL_ID || null,
      meetings: env.MEETINGS_CHANNEL_ID || null,
    },
    pr: {
      labelRoles: labelRolesFromEnv(env),
      defaultRoleIds: env.DEFAULT_PR_ROLE_ID ? [env.DEFAULT_PR_ROLE_ID] : [],
      resendAfterHours: 12,
      emojis: { approved: "✅", merged: "🟣", changesRequested: "🔁" },
    },
    meetings: {
      reminders: [30, 5],
      timezone: "Europe/Kyiv",
    },
  };
}

function merge(base, over) {
  if (!over || typeof over !== "object" || Array.isArray(over)) return over ?? base;
  const out = { ...base };
  for (const [k, v] of Object.entries(over)) {
    if (v === null || v === undefined) continue;
    out[k] = base?.[k] && typeof base[k] === "object" && !Array.isArray(base[k]) ? merge(base[k], v) : v;
  }
  return out;
}

function mergeSettings(defaults, stored) {
  const { id, ...rest } = stored ?? {};
  return merge(defaults, rest);
}

async function loadSettings(fs, env) {
  return mergeSettings(defaultSettings(env), await fs.get("settings/main"));
}

// ---- services/common/src/events.js ----
// Best-effort: analytics must never break the main flow.

async function logEvent(fs, source, type, data = {}, now = new Date()) {
  try {
    await fs.add("events", { type, source, at: now, ...data });
  } catch {}
}

// ---- services/common/src/time.js ----
function zonedParts(date, tz) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: tz, hourCycle: "h23",
    year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit",
  }).formatToParts(date);
  return Object.fromEntries(parts.filter((p) => p.type !== "literal").map((p) => [p.type, p.value]));
}

function tzOffsetMs(date, tz) {
  const p = zonedParts(date, tz);
  return Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute, +p.second) - Math.floor(date / 1000) * 1000;
}

// "2026-11-23" + "15:00" in tz → Date (UTC instant); correct across DST changes
function zonedToUtc(dateStr, timeStr, tz) {
  const [y, m, d] = dateStr.split("-").map(Number);
  const [h, mi] = timeStr.split(":").map(Number);
  const wall = Date.UTC(y, m - 1, d, h, mi);
  let t = wall - tzOffsetMs(new Date(wall), tz);
  t = wall - tzOffsetMs(new Date(t), tz);
  return new Date(t);
}

const WEEKDAYS = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];

function localDate(date, tz) {
  const p = zonedParts(date, tz);
  const iso = `${p.year}-${p.month}-${p.day}`;
  return { iso, weekday: WEEKDAYS[new Date(`${iso}T12:00:00Z`).getUTCDay()] };
}

const addDays = (iso, n) => new Date(Date.parse(`${iso}T12:00:00Z`) + n * 864e5).toISOString().slice(0, 10);

const weekdayOf = (iso) => WEEKDAYS[new Date(`${iso}T12:00:00Z`).getUTCDay()];

// whole weeks between the Mondays of two dates
function weeksBetween(fromIso, toIso) {
  const monday = (iso) => {
    const t = Date.parse(`${iso}T12:00:00Z`);
    return t - ((new Date(t).getUTCDay() + 6) % 7) * 864e5;
  };
  return Math.round((monday(toIso) - monday(fromIso)) / (7 * 864e5));
}

const unixSeconds = (date) => Math.floor(new Date(date).getTime() / 1000);

// ---- services/reminders/src/schedule.js ----

const occurrenceId = (meetingId, date, time) => `${meetingId}_${date}_${time.replace(":", "")}`;

function slotsOn(meeting, iso) {
  if (meeting.startDate && iso < meeting.startDate) return [];
  if (meeting.endDate && iso > meeting.endDate) return [];
  const slots = meeting.slots ?? [];
  if (meeting.type === "once") return slots.filter((s) => s.date === iso);
  const weekday = weekdayOf(iso);
  const onDay = slots.filter((s) => s.weekday === weekday);
  if (meeting.type === "weekly") return onDay;
  if (meeting.type === "interval") {
    const every = Math.max(1, Number(meeting.everyWeeks) || 1);
    const weeks = weeksBetween(meeting.startDate ?? iso, iso);
    return weeks >= 0 && weeks % every === 0 ? onDay : [];
  }
  return [];
}

// occurrences whose start lies in [from, to]
function occurrencesBetween(meetings, exceptions, from, to, defaults) {
  const byKey = new Map(exceptions.map((x) => [`${x.meetingId}|${x.date}`, x]));
  const out = [];
  for (const m of meetings) {
    if (m.active === false) continue;
    const tz = m.timezone || defaults.timezone;
    const first = addDays(localDate(new Date(from), tz).iso, -1);
    const last = addDays(localDate(new Date(to), tz).iso, 1);
    for (let iso = first; iso <= last; iso = addDays(iso, 1)) {
      for (const slot of slotsOn(m, iso)) {
        const ex = byKey.get(`${m.id}|${iso}`);
        if (ex?.action === "cancel") continue;
        const moved = ex?.action === "move";
        const date = moved && ex.newDate ? ex.newDate : iso;
        const time = moved && ex.newTime ? ex.newTime : slot.time;
        const startsAt = zonedToUtc(date, time, tz);
        if (startsAt < new Date(from) || startsAt > new Date(to)) continue;
        out.push({
          id: occurrenceId(m.id, iso, slot.time),
          meetingId: m.id,
          date: iso,
          startsAt: startsAt.toISOString(),
          title: m.title || null,
          description: m.description || null,
          zoomUrl: (moved && ex.zoomUrl) || m.zoomUrl || null,
          roleIds: slot.roleIds ?? [],
          userIds: slot.userIds ?? [],
          reminders: (m.reminders?.length ? m.reminders : defaults.reminders).map(Number).sort((a, b) => b - a),
          channelId: m.channelId || null,
        });
      }
    }
  }
  return out.sort((a, b) => a.startsAt.localeCompare(b.startsAt));
}

// what is due now for one occurrence, given its meeting_occurrences document
function dueActions(occ, doc, now, maxLateMin = 10) {
  const t = new Date(now).getTime(), start = Date.parse(occ.startsAt), late = maxLateMin * 60000;
  const actions = [];
  for (const minutes of occ.reminders) {
    const fireAt = start - minutes * 60000;
    if (fireAt <= t && t - fireAt <= late && t < start && !doc?.reminderMessages?.[String(minutes)])
      actions.push({ kind: "reminder", minutes });
  }
  if (start <= t && t - start <= late && !doc?.started) actions.push({ kind: "start" });
  return actions;
}

// ---- services/reminders/src/reminder-card.js ----


const REMINDER_COLOR = 0x3fb950;
const SEEN_PREFIX = "Seen by ";

const absentId = (occId) => `mt:absent:${occId}`;
const absentFormId = (occId) => `mt:absentform:${occId}`;
const seenId = (occId) => `mt:seen:${occId}`;

const mentionsOf = (occ) => [...occ.roleIds.map(roleMention), ...occ.userIds.map(userMention)].join(" ");

function reminderButtons(occ, absentEnabled = true) {
  return [row(
    occ.zoomUrl ? linkButton("Join", occ.zoomUrl) : null,
    actionButton("I can't attend today", absentId(occ.id), { disabled: !absentEnabled }),
  )];
}

function buildReminder(occ, minutes, absentCount = 0) {
  const ts = unixSeconds(occ.startsAt);
  const mentions = mentionsOf(occ);
  const fields = [{ name: "Starts", value: `<t:${ts}:t> (<t:${ts}:R>)`, inline: true }];
  if (absentCount > 0) fields.push({ name: "Marked absent", value: String(absentCount), inline: true });
  return {
    content: `${mentions ? `${mentions}! ` : ""}Meeting starts in about ${minutes} minutes`.slice(0, 2000),
    embeds: [{
      title: (occ.title || "Meeting").slice(0, 256),
      ...(occ.description ? { description: occ.description.slice(0, 4000) } : {}),
      fields,
      color: REMINDER_COLOR,
    }],
    components: reminderButtons(occ),
    allowed_mentions: { parse: [], roles: occ.roleIds, users: occ.userIds },
  };
}

const seenLine = (userIds) => (userIds.length ? `${SEEN_PREFIX}${userIds.map(userMention).join(", ")}` : "");

function buildStart(occ, absences, replyTo) {
  const join = occ.zoomUrl ? linkButton("Join", occ.zoomUrl) : null;
  const reference = replyTo ? { message_reference: { message_id: replyTo, fail_if_not_exists: false } } : {};
  if (!absences.length)
    return { content: "**Meeting started**", components: join ? [row(join)] : [], allowed_mentions: { parse: [] }, ...reference };
  const lines = absences.map((a) => `${userMention(a.userId)} — ${String(a.text).replace(/\s+/g, " ").trim()}`);
  let content = `**Meeting started. Absent today (${absences.length}):**\n${lines.join("\n")}`;
  if (content.length > 1800) content = `${content.slice(0, 1797)}...`;
  return { content, components: [row(join, actionButton("OK", seenId(occ.id), { style: 1 }))], allowed_mentions: { parse: [] }, ...reference };
}

function withSeenBy(content, userIds) {
  const base = String(content ?? "").split("\n\n" + SEEN_PREFIX)[0];
  const line = seenLine(userIds);
  return line ? `${base}\n\n${line}` : base;
}

function absentModal(occ, existingText) {
  return {
    custom_id: absentFormId(occ.id),
    title: "I can't attend today",
    components: [row({
      type: 4, custom_id: "status", label: "Status", style: 2, required: true, max_length: 1000,
      placeholder: "Done, in progress, blockers, why you can't attend",
      ...(existingText ? { value: existingText } : {}),
    })],
  };
}

// ---- services/reminders/src/reminder-service.js ----







const MAX_LATE_MIN = 10;

const absenceList = async (fs, occId) =>
  (await fs.query("absences", [["occurrenceId", "==", occId]])).sort((a, b) => String(a.updatedAt).localeCompare(String(b.updatedAt)));

async function tick(ctx) {
  const fs = createFirestore(ctx), discord = createDiscord(ctx);
  const settings = await loadSettings(fs, ctx.env);
  const now = new Date(ctx.now);
  const meetings = await fs.query("meetings", [["active", "==", true]]);
  const longest = Math.max(30, ...meetings.flatMap((m) => m.reminders ?? []), ...settings.meetings.reminders);
  const since = addDays(localDate(now, settings.meetings.timezone).iso, -1);
  const exceptions = await fs.query("meeting_exceptions", [["date", ">=", since]]);
  const occurrences = occurrencesBetween(
    meetings, exceptions,
    new Date(now - MAX_LATE_MIN * 60000), new Date(+now + (longest + 1) * 60000),
    settings.meetings,
  );

  const done = [];
  for (const occ of occurrences) {
    let doc = await fs.get(`meeting_occurrences/${occ.id}`);
    const actions = dueActions(occ, doc, now, MAX_LATE_MIN);
    if (!actions.length) continue;
    const channelId = occ.channelId || settings.channels.meetings;
    if (!channelId) {
      done.push(`${occ.id}: no meetings channel configured`);
      continue;
    }
    doc ??= {
      meetingId: occ.meetingId, date: occ.date, startsAt: occ.startsAt, title: occ.title,
      zoomUrl: occ.zoomUrl, roleIds: occ.roleIds, userIds: occ.userIds,
      channelId, reminderMessages: {}, started: false, seenBy: [],
    };

    for (const action of actions) {
      if (action.kind === "reminder") {
        const absentCount = (await absenceList(fs, occ.id)).length;
        const msg = await discord.postMessage(channelId, buildReminder(occ, action.minutes, absentCount));
        doc.reminderMessages = { ...doc.reminderMessages, [String(action.minutes)]: msg.id };
        await fs.set(`meeting_occurrences/${occ.id}`, doc);
        await logEvent(fs, "reminders", "reminder_sent", { occurrenceId: occ.id, meetingId: occ.meetingId, minutes: action.minutes }, now);
        done.push(`${occ.id}: reminder ${action.minutes} min`);
      } else {
        const absences = await absenceList(fs, occ.id);
        const posted = Object.entries(doc.reminderMessages ?? {}).sort((a, b) => Number(a[0]) - Number(b[0]));
        const msg = await discord.postMessage(channelId, buildStart(occ, absences, posted[0]?.[1]));
        for (const [, messageId] of posted)
          await discord.editMessage(channelId, messageId, { components: reminderButtons(occ, false) }).catch(() => {});
        doc = { ...doc, started: true, startMessageId: msg.id };
        await fs.set(`meeting_occurrences/${occ.id}`, doc);
        await logEvent(fs, "reminders", "meeting_started", { occurrenceId: occ.id, meetingId: occ.meetingId, absent: absences.length }, now);
        done.push(`${occ.id}: started, absent ${absences.length}`);
      }
    }
  }
  return { occurrences: occurrences.length, done };
}

function modalValue(body) {
  for (const c of body.data?.components ?? []) {
    const input = c.component ?? (c.components ?? [])[0];
    if (input?.custom_id === "status") return String(input.value ?? "").trim();
  }
  return "";
}

// custom_id: mt:absent:<occ>, mt:absentform:<occ>, mt:seen:<occ>
async function handleMeetingInteraction(ctx, body) {
  const fs = createFirestore(ctx);
  const [, action, ...rest] = String(body.data?.custom_id ?? "").split(":");
  const occId = rest.join(":");
  const user = interactionUser(body);
  const occ = await fs.get(`meeting_occurrences/${occId}`);
  if (!occ) return ephemeral("This meeting was not found.");

  if (action === "absent" && body.type === InteractionType.COMPONENT) {
    if (occ.started) return ephemeral("This meeting has already started.");
    const existing = await fs.get(`absences/${occId}_${user.id}`);
    return { type: ResponseType.MODAL, data: absentModal({ id: occId }, existing?.text) };
  }

  if (action === "absentform" && body.type === InteractionType.MODAL_SUBMIT) {
    if (occ.started) return ephemeral("This meeting has already started, your status was not saved.");
    const text = modalValue(body);
    if (!text) return ephemeral("The status is empty, nothing was saved.");
    await fs.set(`absences/${occId}_${user.id}`, {
      occurrenceId: occId, meetingId: occ.meetingId, date: occ.date,
      userId: user.id, userName: user.name, text, updatedAt: ctx.now,
    });
    await logEvent(fs, "reminders", "absence_marked", { occurrenceId: occId, meetingId: occ.meetingId, userId: user.id }, ctx.now);
    return ephemeral("Saved. Your status will be shown when the meeting starts.");
  }

  if (action === "seen" && body.type === InteractionType.COMPONENT) {
    const seenBy = [...new Set([...(occ.seenBy ?? []), user.id])];
    await fs.update(`meeting_occurrences/${occId}`, { seenBy });
    return {
      type: ResponseType.UPDATE_MESSAGE,
      data: {
        content: withSeenBy(body.message?.content, seenBy),
        components: body.message?.components ?? [],
        allowed_mentions: { parse: [] },
      },
    };
  }

  return ephemeral("Unknown action.");
}


